/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const { appliedFilters } = event.payload;

	let instance_state = [];
	let stateToDisplayNameMap = {'1': 'Not Started', '2': 'In Progress', '3': 'Completed', '4': 'Past Due'};
	const {source, values = []} = appliedFilters[0];
	const {payload: {table, field}} = source;

	if (table == "cmdb_data_management_policy_execution" && field == 'instance_state') {
		if (values && values.length > 0) {
			instance_state = values.map((state) => stateToDisplayNameMap[state]);
			instance_state.sort();
			return {
				event: 'Cert Dashboard: Instance filters applied',
				value: {'filter': 'instance state', 'value': instance_state.join(',')}
			};
		}
	}
}

